      "description": "The context for the question",
      "title": "Context",
      "type": "string"
    },
    "coworker": {
      "description": "The role/name of the coworker to ask",
      "title": "Coworker",
      "type": "string"
    }
  },
  "required": [
    "question",
    "context",
    "coworker"
  ],
  "title": "AskQuestionToolSchema",
  "type": "object",
  "additionalProperties": false
